#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
        }
    }

    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};

    queue<vector<int>> q;
    // 初始位置：猎手(n/2-1, m/2-1)，幻影(n/2, m/2)
    q.push({n / 2 - 1, m / 2 - 1, n / 2, m / 2});

    vector<vector<bool>> vis(n, vector<bool>(m, false));
    int ans = 0;

    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int hr = cur[0], hc = cur[1], pr = cur[2], pc = cur[3];

        if (vis[hr][hc]) continue;
        vis[hr][hc] = true;

        if (grid[pr][pc] == 1) {
            ++ans;
            continue;
        }

        for (int i = 0; i < 4; ++i) {
            int nhr = hr + dr[i];
            int nhc = hc + dc[i];
            int npr = pr - dr[i];
            int npc = pc - dc[i];

            if (nhr < 0 || nhr >= n || nhc < 0 || nhc >= m) continue;
            if (grid[nhr][nhc] == 1) continue;
            if (npr < 0 || npr >= n || npc < 0 || npc >= m) continue;

            q.push({nhr, nhc, npr, npc});
        }
    }

    cout << ans << endl;
    return 0;
}
